package org.example.spotifymixer.runtime;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.media.*;import android.media.session.*;import android.os.*;import android.view.*;import android.widget.*;import android.text.*;import android.animation.*;import org.json.*;import java.util.*;import java.util.function.*;import org.example.spotifymixer.ui.*;
/** Real opt-in tool surfaces. Native capability absence is visible, never simulated as success. */
final class ToolsPanel {
 private final Activity activity;private final LinearLayout body;private final SharedPreferences prefs;private final FeatureCatalog.Feature feature;private final String playlist,title;private final Runnable rebuild,spotify;
 private volatile boolean closed,busy;private Thread worker;private MediaController observed;private MediaController.Callback callback;private ValueAnimator animation;
 ToolsPanel(Activity a,LinearLayout body,SharedPreferences prefs,String id,String playlist,String title,Runnable rebuild,Runnable spotify){this.activity=a;this.body=body;this.prefs=prefs;this.feature=FeatureCatalog.find(id);this.playlist=playlist;this.title=title;this.rebuild=rebuild;this.spotify=spotify;try{render();}catch(Exception error){note(body,"This tool is unavailable: "+(error.getMessage()==null?error.getClass().getSimpleName():error.getMessage()));}}
 private TextView text(LinearLayout box,String value,int size,boolean bold){return EnhancerPanel.label(box,value,size,EnhancerPanel.WHITE,bold);}
 private TextView note(LinearLayout box,String value){return EnhancerPanel.label(box,value,12,EnhancerPanel.MUTED,false);}
 private Button button(LinearLayout box,String value,boolean primary,Runnable action){return EnhancerPanel.button(box,value,primary,()->{try{action.run();}catch(Exception e){failure(e);}});}
 private void failure(Exception e){Throwable root=e;while(root.getCause()!=null)root=root.getCause();Toast.makeText(activity,root.getMessage()==null?root.getClass().getSimpleName():root.getMessage(),Toast.LENGTH_LONG).show();}
 private boolean enabled(){return prefs.getBoolean(feature.key(),false);}
 private boolean save(SharedPreferences.Editor editor){if(!editor.commit()){failure(new Exception("Could not save settings"));return false;}return true;}
 private Switch toggle(LinearLayout box,String label,String key,boolean fallback,Runnable changed){Switch s=new Switch(new ContextThemeWrapper(activity,android.R.style.Theme_Material_NoActionBar));s.setText(label);s.setTextColor(EnhancerPanel.WHITE);EnhancerPanel.styleSwitch(s);s.setChecked(prefs.getBoolean(key,fallback));box.addView(s,new LinearLayout.LayoutParams(-1,EnhancerPanel.dp(activity,52)));s.setOnCheckedChangeListener((v,on)->{if(save(prefs.edit().putBoolean(key,on)))changed.run();});return s;}
 private EditText input(LinearLayout box,String label,String initial,boolean number){EditText field=new EditText(new ContextThemeWrapper(activity,android.R.style.Theme_Material_NoActionBar));field.setSingleLine(true);field.setTextColor(EnhancerPanel.WHITE);field.setHintTextColor(EnhancerPanel.MUTED);field.setHint(label);field.setContentDescription(label);field.setText(initial);field.setInputType(number?android.text.InputType.TYPE_CLASS_NUMBER:android.text.InputType.TYPE_CLASS_TEXT);field.setBackground(EnhancerPanel.surface(EnhancerPanel.CARD,12,activity,true));field.setPadding(20,10,20,10);box.addView(field,new LinearLayout.LayoutParams(-1,EnhancerPanel.dp(activity,52)));return field;}
 private int number(EditText input,int min,int max){int value;try{value=Integer.parseInt(input.getText().toString().trim());}catch(NumberFormatException e){throw new IllegalArgumentException("Enter a whole number");}if(value<min||value>max)throw new IllegalArgumentException("Choose "+min+"–"+max);return value;}
 private Spinner choices(LinearLayout box,String label,String[] values,int selected){Spinner s=new Spinner(new ContextThemeWrapper(activity,android.R.style.Theme_Material_NoActionBar));s.setAdapter(new ArrayAdapter<String>(s.getContext(),android.R.layout.simple_spinner_dropdown_item,values));s.setContentDescription(label);s.setSelection(Math.max(0,Math.min(values.length-1,selected)));box.addView(s,new LinearLayout.LayoutParams(-1,EnhancerPanel.dp(activity,52)));return s;}
 private void refresh(){ThemeRuntime.refresh(activity);EqualizerRuntime.refresh();EnhancementRuntime.refresh();}
 private void render(){
  text(body,feature.title,26,true);note(body,feature.subtitle);
  if(feature.limit!=null){note(body,feature.limit);Button unavailable=button(body,"Not available in this build",false,()->{});unavailable.setEnabled(false);return;}
  toggle(body,"Enable "+feature.title,feature.key(),false,()->{refresh();rebuild.run();});
  if(!enabled()){note(body,"Off. Enable this feature to use its controls.");return;}
  switch(feature.id){
   case "sleep":sleep();break;case "cinema":cinema();break;case "artwork":note(body,"Animated colors from the current album cover, inside Cinema Player. No artwork is downloaded or changed.");openCinema();break;
   case "duplicates":scan(false);break;case "find":scan(true);break;case "rediscover":rediscover();break;
   case "confirm_clear":clearQueue();break;case "queue_search":queue();break;case "queue_undo":undo();break;case "clean_share":cleanShare();break;
   case "volume":volume();break;case "rules":rules();break;case "guard":note(body,"Our Start Mix, Queue Undo restore and Rediscover play actions ask before replacing playback. Native Spotify play buttons and remote Connect commands are not intercepted.");break;
   case "quick_search":quickSearch();break;case "seek":note(body,"Shows ±10 and ±30 second controls in Cinema Player when the local media session supports seeking.");openCinema();break;
   case "skip_guard":note(body,"Cinema skip buttons and foreground media-next/previous key events need a second press within 1.5 seconds. Native Spotify on-screen skip buttons, background headset events and Connect are not intercepted.");openCinema();break;
   case "amoled":note(body,"True black backgrounds through the existing supported native color conversion and Android-view theme path. Artwork and custom drawing are preserved. Reopen Spotify screens to refresh cached colors.");button(body,"Reopen Spotify screen",false,()->ThemeRuntime.reopen(activity));break;
   case "compact":note(body,"Reduces supported Android RecyclerView row padding/heights, keeping a 48dp minimum touch target. Compose and custom-drawn Spotify lists may remain unchanged. Disable restores tracked view properties.");break;
   case "track_info":note(body,"Allows up to three lines for Android TextViews matching the current track title or artist. Native Compose/custom text and truncated strings Spotify does not publish are not replaced.");break;
   case "start":startPage();break;case "profiles":profiles();break;
  }
 }
 private void openCinema(){if(!prefs.getBoolean("cinema_enabled",false))note(body,"Enable Cinema Player separately to open it.");button(body,"Open Cinema Player",false,()->{activity.startActivity(new Intent(activity,SpotEnhancerActivity.class).putExtra("screen","tool:cinema").putExtra("from_spotify",true));activity.finish();});}
 private void sleep(){note(body,MediaToolsRuntime.timerStatus());EditText minutes=input(body,"Sleep timer minutes",Integer.toString(prefs.getInt("sleep_minutes",30)),true);button(body,"Start sleep timer",true,()->{int value=number(minutes,1,1440);if(!save(prefs.edit().putInt("sleep_minutes",value)))return;MediaToolsRuntime.startTimer(value);rebuild.run();}).setEnabled(MediaToolsRuntime.supports(PlaybackState.ACTION_PAUSE));button(body,"Cancel sleep timer",false,()->{MediaToolsRuntime.cancelTimer();rebuild.run();});note(body,"Local playback only. The timer belongs to this process and original session; it is cancelled by process death or session destruction. Android can delay background alarms. A pause request is not proof that sound stopped.");}
 private void cinema(){
  MediaController controller=MediaToolsRuntime.controller();if(controller==null){note(body,MediaToolsRuntime.status());button(body,"Refresh media connection",false,rebuild);return;}
  activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);
  LinearLayout stage=EnhancerPanel.card(body);stage.setGravity(Gravity.CENTER);ImageView artwork=new ImageView(activity);artwork.setContentDescription("Current album artwork");artwork.setScaleType(ImageView.ScaleType.FIT_CENTER);stage.addView(artwork,new LinearLayout.LayoutParams(-1,EnhancerPanel.dp(activity,240)));
  TextView track=text(stage,"",24,true),artist=text(stage,"",16,false);track.setGravity(Gravity.CENTER);artist.setGravity(Gravity.CENTER);track.setMaxLines(4);artist.setMaxLines(3);
  LinearLayout controls=new LinearLayout(activity);controls.setOrientation(1);stage.addView(controls);Button pause=button(controls,"Play / Pause",true,()->{MediaController c=MediaToolsRuntime.controller();PlaybackState state=c==null?null:c.getPlaybackState();if(state!=null&&state.getState()==PlaybackState.STATE_PLAYING)MediaToolsRuntime.pause();else MediaToolsRuntime.play();});
  Button previous=button(controls,"Previous",false,()->MediaToolsRuntime.skip(-1));Button next=button(controls,"Next",false,()->MediaToolsRuntime.skip(1));
  if(prefs.getBoolean("seek_enabled",false)){for(int seconds:new int[]{-30,-10,10,30})button(controls,(seconds>0?"+":"")+seconds+" seconds",false,()->MediaToolsRuntime.seek(seconds*1000L)).setEnabled(MediaToolsRuntime.supports(PlaybackState.ACTION_SEEK_TO));}
  Runnable update=()->{if(closed)return;track.setText(MediaToolsRuntime.title());artist.setText(MediaToolsRuntime.artist());MediaController c=MediaToolsRuntime.controller();MediaMetadata m=c==null?null:c.getMetadata();Bitmap bitmap=m==null?null:m.getBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART);if(bitmap==null&&m!=null)bitmap=m.getBitmap(MediaMetadata.METADATA_KEY_ART);artwork.setImageBitmap(bitmap);PlaybackState s=c==null?null:c.getPlaybackState();boolean playing=s!=null&&s.getState()==PlaybackState.STATE_PLAYING;pause.setText(playing?"Pause":"Play");pause.setEnabled(MediaToolsRuntime.supports(playing?PlaybackState.ACTION_PAUSE:PlaybackState.ACTION_PLAY));previous.setEnabled(MediaToolsRuntime.supports(PlaybackState.ACTION_SKIP_TO_PREVIOUS));next.setEnabled(MediaToolsRuntime.supports(PlaybackState.ACTION_SKIP_TO_NEXT));if(animation!=null){animation.cancel();animation=null;}if(prefs.getBoolean("artwork_enabled",false))animate(stage,bitmap);};
  update.run();observed=controller;callback=new MediaController.Callback(){public void onMetadataChanged(MediaMetadata value){update.run();}public void onPlaybackStateChanged(PlaybackState value){update.run();}public void onSessionDestroyed(){if(!closed)rebuild.run();}};observed.registerCallback(callback,MediaToolsRuntime.MAIN);note(body,"Controls follow published media-session capabilities. Remote playback is read-only here. Missing artwork is left empty.");
 }
 private void animate(LinearLayout stage,Bitmap bitmap){int color=0xff1d4930;try{if(bitmap!=null){long red=0,green=0,blue=0;int count=0;for(int y=0;y<8;y++)for(int x=0;x<8;x++){int c=bitmap.getPixel(Math.min(bitmap.getWidth()-1,x*bitmap.getWidth()/8),Math.min(bitmap.getHeight()-1,y*bitmap.getHeight()/8));red+=Color.red(c);green+=Color.green(c);blue+=Color.blue(c);count++;}color=Color.rgb((int)(red/count),(int)(green/count),(int)(blue/count));}}catch(RuntimeException ignored){}float[] hsv=new float[3];Color.colorToHSV(color,hsv);hsv[2]=.18f;int first=Color.HSVToColor(hsv);hsv[0]=(hsv[0]+35)%360;hsv[2]=.28f;int second=Color.HSVToColor(hsv);GradientDrawable background=EnhancerPanel.surface(first,16,activity,false);stage.setBackground(background);animation=ValueAnimator.ofFloat(0,1);animation.setDuration(8000);animation.setRepeatCount(ValueAnimator.INFINITE);animation.setRepeatMode(ValueAnimator.REVERSE);animation.addUpdateListener(a->{float t=(Float)a.getAnimatedValue();int mixed=Color.rgb((int)(Color.red(first)*(1-t)+Color.red(second)*t),(int)(Color.green(first)*(1-t)+Color.green(second)*t),(int)(Color.blue(first)*(1-t)+Color.blue(second)*t));background.setColors(new int[]{first,mixed,0xff101314});});animation.start();}
 private void queue(){note(body,"Only the queue window Spotify publishes to Android is shown. It may be empty or smaller than the full native queue.");EditText search=input(body,"Search published queue","",false);LinearLayout rows=new LinearLayout(activity);rows.setOrientation(1);body.addView(rows);List<MediaSession.QueueItem> items=MediaToolsRuntime.queue();Runnable render=()->{rows.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT);int matched=0;for(MediaSession.QueueItem item:items){String title=String.valueOf(item.getDescription().getTitle()),sub=String.valueOf(item.getDescription().getSubtitle());if(!(title+" "+sub).toLowerCase(Locale.ROOT).contains(query))continue;matched++;if(matched>100)continue;LinearLayout row=EnhancerPanel.card(rows);text(row,title,prefs.getBoolean("compact_enabled",false)?14:17,true);note(row,sub.equals("null")?"":sub);button(row,"Play this queue item",false,()->MediaToolsRuntime.jump(item.getQueueId())).setEnabled(MediaToolsRuntime.supports(PlaybackState.ACTION_SKIP_TO_QUEUE_ITEM));}if(matched>100)note(rows,"Showing 100 of "+matched+" matches. Refine your search to see another result.");if(matched==0)note(rows,items.isEmpty()?"No published queue items. Start local playback and refresh.":"No matches in the published queue.");};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}});render.run();button(body,"Refresh published queue",false,rebuild);}
 private void undo(){note(body,"Snapshots contain only Android-published canonical track items. Spotify may publish a partial queue. Restore restarts this saved list from the beginning, unshuffled; it cannot preserve manual/context partitions, playback position or remote-device state.");button(body,"Save published queue snapshot",true,()->{MediaToolsRuntime.snapshot();rebuild.run();}).setEnabled(!MediaToolsRuntime.queue().isEmpty());List<String> saved=MediaToolsRuntime.savedQueue();note(body,saved.isEmpty()?"No snapshot saved.":saved.size()+" published tracks saved · "+java.text.DateFormat.getDateTimeInstance().format(new Date(prefs.getLong("queue_snapshot_time",0))));button(body,"Restore saved track list",false,()->confirm("Restore this saved track list?","This replaces playback with "+saved.size()+" tracks and starts from the beginning.",()->run("Restoring track list…",()->{new NativeBridge().play(saved,false);return "Spotify accepted the saved track list; check playback.";}))).setEnabled(!saved.isEmpty()&&NativeBridge.ready());button(body,"Delete saved snapshot",false,()->{confirm("Delete saved snapshot?","This only deletes the local snapshot, not Spotify's queue.",()->{save(prefs.edit().remove("queue_snapshot").remove("queue_snapshot_time"));rebuild.run();});});}
 private void clearQueue(){
  note(body,"This SpotEnhancer action clears the native upcoming queue window after confirmation, preserving current playback and previous items. Spotify may refill context/autoplay items. Native Spotify clear/reorder buttons are not intercepted. Never auto-retries a write.");
  if(!NativeBridge.ready()||!MediaToolsRuntime.local(MediaToolsRuntime.controller())){note(body,"Start local playback to connect the native player and media session, then reopen this tool.");return;}
  final QueueClearSession session;try{session=NativeQueue.session(prefs);}catch(Exception e){failure(e);return;}
  LinearLayout output=new LinearLayout(activity);output.setOrientation(1);body.addView(output);
  if(prefs.contains("queue_clear_pending")){note(body,"An earlier clear is unconfirmed. Only read-only verification is available.");button(body,"Verify last clear",true,()->background(output,"Reading native queue…",()->session.verify(),snapshot->{note(output,"Upcoming native queue is empty; recovery record cleared.");}));button(body,"Forget after checking Spotify",false,()->confirm("Have you checked Spotify's queue?","This only forgets the local recovery record. A previous request may already have changed the queue.",()->{save(prefs.edit().remove("queue_clear_pending"));rebuild.run();}));return;}
  button(body,"Review upcoming queue",true,()->background(output,"Reading native queue revision…",()->session.preview(),snapshot->{note(output,snapshot.next.size()+" upcoming items · "+snapshot.previous.size()+" previous items");if(snapshot.next.isEmpty()){note(output,"Upcoming native queue is already empty.");return;}button(output,"Clear upcoming queue…",false,()->confirm("Clear upcoming native queue?","Remove "+snapshot.next.size()+" upcoming items? Current playback is preserved. If the queue changed, no write is sent.",()->background(output,"Sending one confirmed clear request…",()->{if(!enabled()||!MediaToolsRuntime.local(MediaToolsRuntime.controller()))throw new IllegalStateException("Feature or local playback is no longer available");session.clear(snapshot);return "Upcoming native queue verified empty. No play command was sent.";},result->note(output,result))));}));
 }
 private void cleanShare(){String uri=MediaToolsRuntime.currentTrack();if(uri==null)uri=playlist;final String selected=uri;note(body,selected==null?"Open a playlist or play a recognized track first.":"Copy a canonical link without tracking parameters. Spotify's native Share menu is not intercepted.");button(body,"Copy clean Spotify link",true,()->{String link=EnhancementTools.cleanLink(selected);((android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Spotify",link));Toast.makeText(activity,"Clean link copied",Toast.LENGTH_SHORT).show();}).setEnabled(selected!=null);}
 private void quickSearch(){EditText query=input(body,"Search music, artists or playlists","",false);button(body,"Search in Spotify",true,()->{String term=query.getText().toString().trim();if(term.isEmpty())throw new IllegalArgumentException("Enter a search term");EnhancementRuntime.navigate(activity,"spotify:search:"+android.net.Uri.encode(term));activity.finish();});}
 private void volume(){EditText steps=input(body,"Volume steps (1–10)",Integer.toString(prefs.getInt("volume_steps",1)),true);button(body,"Save volume steps",true,()->{save(prefs.edit().putInt("volume_steps",number(steps,1,10)));rebuild.run();});note(body,"Each volume key press changes the local music-stream volume by this many Android steps while a Spotify window is in the foreground. The music-stream volume is shared by local apps. Background/headset buttons and remote Connect volume are unchanged.");}
 private void rules(){toggle(body,"Pause when headphones disconnect","rules_pause",true,EnhancementRuntime::refresh);toggle(body,"Resume when headphones connect","rules_resume",false,EnhancementRuntime::refresh);note(body,"Opt-in output-device events for wired/USB/Bluetooth headphones. Actions require a published local media session and supported transport action. Existing devices at enable time do not trigger resume. No effect on remote Connect speakers.");}
 private void startPage(){String[] names={"Home","Your playlists","Search"},routes={"spotify:home","spotify:collection:playlists","spotify:search"};int selected=Arrays.asList(routes).indexOf(prefs.getString("start_route",routes[0]));Spinner s=choices(body,"Spotify start page",names,selected);button(body,"Save start page",true,()->{save(prefs.edit().putString("start_route",routes[s.getSelectedItemPosition()]));Toast.makeText(activity,"Applies on the next launcher process start",Toast.LENGTH_LONG).show();});note(body,"Runs once per process when MainActivity opens from the launcher. Explicit deep links and notifications are preserved. It does not force-stop Spotify.");}
 private LinkedHashMap<String,String> sources()throws Exception{LinkedHashMap<String,String> result=new LinkedHashMap<>();if(playlist!=null)result.put(playlist,title==null?"Current playlist":title);MixLibrary library=new MixLibrary(prefs);for(MixConfig.Source source:library.active().sources)result.put(source.uri,source.title);for(boolean history:new boolean[]{false,true})for(MixLibrary.Entry entry:library.entries(history))for(MixConfig.Source source:entry.config.sources)result.put(source.uri,source.title);return result;}
 private void scan(boolean find){
  note(body,find?"Find the current track in your mixer sources, presets and history. This does not scan your entire Spotify library.":"Read-only scan for repeated canonical track IDs. Alternate recordings/releases with different IDs are not merged. No track is removed.");
  LinkedHashMap<String,String> sources;try{sources=sources();}catch(Exception e){failure(e);return;}
  if(sources.isEmpty()){note(body,"Open a playlist or add mixer sources first.");button(body,"Open your playlists",false,()->{EnhancementRuntime.navigate(activity,"spotify:collection:playlists");activity.finish();});return;}
  List<String> uris=new ArrayList<>(sources.keySet());Spinner pick=choices(body,"Playlist to check",sources.values().toArray(new String[0]),0);LinearLayout result=new LinearLayout(activity);result.setOrientation(1);body.addView(result);
  if(find){String track=MediaToolsRuntime.currentTrack();note(body,MediaToolsRuntime.title());button(body,"Find current track",true,()->{final String target=MediaToolsRuntime.currentTrack();if(target==null)throw new IllegalArgumentException("No recognized current Spotify track");background(result,"Checking selected playlist sources…",()->{List<String[]> found=new ArrayList<>();NativeBridge bridge=new NativeBridge();for(String uri:uris){if(Thread.currentThread().isInterrupted())throw new InterruptedException();MixSession.Playlist p=bridge.load(uri,message->{});if(p.tracks.contains(target))found.add(new String[]{uri,p.title.isEmpty()?sources.get(uri):p.title});}return found;},found->{if(found.isEmpty())note(result,"No match in the checked playlist sources.");for(String[] p:found)button(result,p[1],false,()->{EnhancementRuntime.navigate(activity,p[0]);activity.finish();});});}).setEnabled(track!=null&&NativeBridge.playlistReady());}
  else button(body,"Scan for duplicates",true,()->{String uri=uris.get(pick.getSelectedItemPosition());background(result,"Loading complete playlist…",()->new NativeBridge().load(uri,message->{}),loaded->{text(result,loaded.title.isEmpty()?sources.get(uri):loaded.title,18,true);Map<String,Integer> dupes=EnhancementTools.duplicates(loaded.tracks);note(result,loaded.tracks.size()+" rows checked · "+dupes.size()+" repeated track IDs");int displayed=0;for(Map.Entry<String,Integer> e:dupes.entrySet()){if(displayed++>=100)break;String id=e.getKey();button(result,id.substring(14)+" · "+e.getValue()+" occurrences",false,()->EnhancementRuntime.navigate(activity,id));}if(dupes.size()>100)note(result,"Showing the first 100 repeated IDs; all playlist rows were checked.");if(dupes.isEmpty())note(result,"No duplicate canonical track IDs found.");});}).setEnabled(NativeBridge.playlistReady());
 }
 private void rediscover(){note(body,"Listening history starts when this feature is enabled. A playing-track event is recorded, not a full listen or Spotify's historical account data. Up to 1,000 unique tracks are retained locally.");EditText days=input(body,"Minimum days since last observed play","7",true);LinearLayout rows=new LinearLayout(activity);rows.setOrientation(1);body.addView(rows);Runnable show=()->{rows.removeAllViews();int age=number(days,0,3650);try{JSONArray log=new JSONArray(prefs.getString("rediscover_log","[]"));long before=System.currentTimeMillis()-age*86400000L;int found=0;for(int i=log.length()-1;i>=0;i--){JSONObject row=log.getJSONObject(i);if(row.getLong("time")>before)continue;String uri=EnhancementTools.track(row.optString("uri"));if(uri==null)continue;found++;if(found>100)continue;LinearLayout card=EnhancerPanel.card(rows);text(card,row.optString("title",uri),16,true);note(card,row.optString("artist","")+" · "+java.text.DateFormat.getDateInstance().format(new Date(row.getLong("time"))));button(card,"Play again",false,()->replace("Play this rediscovered track?",()->run("Sending track…",()->{new NativeBridge().play(Collections.singletonList(uri),false);return "Spotify accepted the track; check playback.";}))).setEnabled(NativeBridge.ready());}if(found>100)note(rows,"Showing the 100 oldest matching tracks.");if(found==0)note(rows,"No observed tracks this old yet.");}catch(JSONException e){failure(e);}};button(body,"Show older tracks",true,show);show.run();button(body,"Clear local listening history",false,()->confirm("Clear local listening history?","Spotify account history is not changed.",()->{save(prefs.edit().remove("rediscover_log"));rebuild.run();}));}
 private void profiles(){SettingsProfiles profiles=new SettingsProfiles(prefs);EditText name=input(body,"Settings profile name","",false);button(body,"Save settings profile",true,()->{try{profiles.save(name.getText().toString());rebuild.run();}catch(Exception e){failure(e);}});note(body,"Profiles contain enhancer settings only. They exclude accounts, mixer sources/history, creator requests, listening history, queue snapshots and running timers.");try{JSONObject all=profiles.all();Iterator<String> names=all.keys();while(names.hasNext()){String key=names.next();LinearLayout card=EnhancerPanel.card(body);text(card,key,17,true);button(card,"Apply profile",false,()->confirm("Apply settings profile?","Your current enhancer settings will be replaced.",()->{try{profiles.apply(key);refresh();rebuild.run();}catch(Exception e){failure(e);}}));button(card,"Delete profile",false,()->confirm("Delete settings profile?",key,()->{try{profiles.delete(key);rebuild.run();}catch(Exception e){failure(e);}}));}}catch(JSONException e){failure(e);}}
 private void replace(String title,Runnable yes){if(prefs.getBoolean("guard_enabled",false))confirm(title,"This replaces the current playback session.",yes);else yes.run();}
 private void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(activity,android.R.style.Theme_Material_Dialog_Alert).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->{if(!closed)try{yes.run();}catch(Exception e){failure(e);}}).show();}
 private interface Job<T>{T get()throws Exception;}
 private <T> void background(LinearLayout result,String message,Job<T> job,Consumer<T> done){if(busy)throw new IllegalStateException("Wait for the current tool operation");busy=true;result.removeAllViews();TextView status=note(result,message);worker=new Thread(()->{try{T value=job.get();activity.runOnUiThread(()->{if(!closed){result.removeAllViews();try{done.accept(value);}catch(RuntimeException e){failure(e);}}});}catch(Exception error){activity.runOnUiThread(()->{if(!closed)status.setText("Could not complete: "+(error.getMessage()==null?error.getClass().getSimpleName():error.getMessage()));if(!closed&&feature.id.equals("confirm_clear")&&prefs.contains("queue_clear_pending"))button(result,"Open recovery options",false,rebuild);});}finally{busy=false;}},"spotenhancer-tool");worker.start();}
 private void run(String message,Job<String> job){LinearLayout output=new LinearLayout(activity);output.setOrientation(1);body.addView(output);background(output,message,job,value->note(output,value));}
 void close(){closed=true;if(worker!=null)worker.interrupt();if(animation!=null)animation.cancel();if(observed!=null&&callback!=null)observed.unregisterCallback(callback);activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);}
}
